class _Chainable:
    """An object, where input and output configuration have to match when merged"""

    # every variable is derived as a subclass
    # every instance represents a certain entry in that class

    def __init__(
        self,
        input_config=None,
        output_config=None,
    ):
        self._inp_config = None
        self._out_config = None
        self.input_config = input_config
        self.output_config = output_config

    @property
    def config(self):
        """access config for fast access"""
        return (self.input_config, self.output_config)

    @property
    def input_config(self):
        """access read-only attribute input_config"""
        if self._inp_config is None:
            return None
        return self._inp_config()

    @input_config.setter
    def input_config(self, target):
        if target is None:
            inp_config = None
        else:
            inp_config = weakref.ref(target)
        self._inp_config = inp_config

    @property
    def output_config(self):
        """access read-only attribute output_config"""
        if self._out_config is None:
            return None
        return self._out_config()

    @output_config.setter
    def output_config(self, target):
        if target is None:
            out_config = None
        else:
            out_config = weakref.ref(target)
        self._out_config = out_config

    def combine(self, other):
        """combine two chainables"""
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible Variables cannot be combined")
        return _Chainable(
            input_config=self.input_config, output_config=other.output_config
        )

    def __or__(self, other):
        return self.combine(other)

    @staticmethod
    def is_compatible(first, second):
        """check if the variables fit together"""
        if first.output_config is not None:
            if second.input_config is not None:
                if first.output_config != second.input_config:
                    return False
        return True


class InstructionVariable(_Chainable):
    """Instruction Variable is a chainable"""

    _name = "DEFAULT"

    def __init__(self, offsets=None, input_config=None, output_config=None):
        if offsets is None:
            output_config = input_config
        super().__init__(
            input_config=input_config, output_config=output_config
        )
        if offsets is None:
            offsets = []
        self._offsets = offsets

    def __init_subclass__(cls, name=None):
        if name is None:
            name = cls.__name__
        cls._name = name

    @classmethod
    def new(cls, name):
        """generate a new class"""
        if not isinstance(name, str):
            raise ValueError("Name must be a string")
        newclass = type(name, (InstructionVariable,), {})
        return newclass

    def __str__(self):
        offset = (
            f"({'|'.join(map(str, self.offsets))})" if self.offsets else "O"
        )
        return f"<{self.name}+{offset}>"

    def __repr__(self):
        return str(self)
        # return f"<{self._name}>"

    @property
    def name(self):
        """access offsets"""
        return self._name

    @property
    def offsets(self):
        """access offsets"""
        return list(self._offsets)

    def append_offset(self, offset):
        """access total offset"""
        if not isinstance(offset, InstructionVariableOffset):
            raise TypeError("Offset must be an InstructionVariableOffset")
        if not _Chainable.is_compatible(self, offset):
            raise ValueError("Incompatible offsets cannot be combined")
        ret = InstructionVariable(offsets=self._offsets + [offset])
        ret.output_config = offset.output_config
        return ret

    def merge(self, other):
        """merge an instruction variable with another one"""
        if not isinstance(other, InstructionVariable):
            raise TypeError("Merging partner must be an InstructionVariable")
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible variables cannot be combined")
        return InstructionVariable(
            offsets=self._offsets + other.offsets,
            input_config=self.input_config,
            output_config=other.output_config,
        )

